// Lab ground truth: a deliberately vulnerable "vibe-coded" app, generated on demand.
// Fake secrets are assembled at runtime so this repository never contains a
// string that looks like a real key.
import { execFileSync } from 'node:child_process';
import { mkdir, writeFile } from 'node:fs/promises';
import http from 'node:http';
import path from 'node:path';

const b64url = (obj) => Buffer.from(JSON.stringify(obj)).toString('base64url');
export const fakeJwt = (role) =>
  `${b64url({ alg: 'HS256', typ: 'JWT' })}.${b64url({ iss: 'supabase', ref: 'labproject', role })}.${'Qm9ndXNTaWduYXR1cmVGb3JMYWI'}`;
export const FAKE_STRIPE = 'sk_' + 'live_' + '51LabOnlyNotARealKey0000AbCd';

/** Planted flaws and the rule each one must trigger. */
export const REPO_EXPECTED = [
  'VSC-DB-001', // profiles: no RLS
  'VSC-DB-002', // posts: write-anyone policy
  'VSC-DB-004', // service_role used in client code
  'VSC-DB-006', // service_role JWT in committed .env
  'VSC-ENV-001', // .env tracked by git
  'VSC-ENV-002', // VITE_ secret-named variable
  'VSC-ENV-003', // no lockfile
  'VSC-SEC-002', // Stripe key, only in git history
];

const git = (cwd, ...args) =>
  execFileSync('git', ['-c', 'user.name=lab', '-c', 'user.email=lab@example.invalid', '-c', 'commit.gpgsign=false', ...args], { cwd, stdio: 'pipe' });

export async function createVulnerableRepo(dir) {
  const write = async (rel, content) => {
    await mkdir(path.dirname(path.join(dir, rel)), { recursive: true });
    await writeFile(path.join(dir, rel), content);
  };
  await write('package.json', JSON.stringify({ name: 'lab-vibe-app', private: true }, null, 2));
  await write('supabase/migrations/0001_init.sql', `
-- Generated by an AI assistant
create table public.profiles (id uuid primary key, email text, full_name text);

create table public.posts (id serial primary key, author uuid, body text);
alter table public.posts enable row level security;
create policy "anyone can do anything" on public.posts for all using (true) with check (true);

create table public.notes (id serial primary key, owner_id uuid, body text);
alter table public.notes enable row level security;
create policy "owners read notes" on public.notes for select to authenticated using (auth.uid() = owner_id);
`);
  await write('src/lib/admin.ts', `import { createClient } from '@supabase/supabase-js';
export const admin = createClient(import.meta.env.VITE_SUPABASE_URL, import.meta.env.VITE_SUPABASE_SERVICE_ROLE_KEY);
`);
  await write('src/App.tsx', `export default function App() { return <div>Lab app</div>; }\n`);
  await write('supabase/functions/admin/index.ts', `// server-only, must NOT be flagged\nconst key = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');\n`);
  await write('.env', `VITE_SUPABASE_URL=https://labprojectabcdefghij.supabase.co\nSUPABASE_SERVICE_ROLE_KEY=${fakeJwt('service_role')}\n`);
  await write('src/payments.ts', `const stripe = "${FAKE_STRIPE}";\n`);

  git(dir, 'init', '-q', '-b', 'main');
  git(dir, 'add', '-A');
  git(dir, 'commit', '-q', '-m', 'initial vibe-coded app');
  // The secret is "removed" but stays in history.
  await write('src/payments.ts', `const stripe = process.env.STRIPE_KEY;\n`);
  git(dir, 'commit', '-q', '-am', 'move stripe key to env');
}

export const WEB_EXPECTED = ['VSC-WEB-001', 'VSC-WEB-003', 'VSC-WEB-004', 'VSC-WEB-005', 'VSC-DB-005', 'VSC-DB-006'];

/** Local HTTP server that imitates a deployed app plus its Supabase REST API. */
export async function startVulnerableServer() {
  const anon = fakeJwt('anon');
  const server = http.createServer((req, res) => {
    const url = new URL(req.url, 'http://localhost');
    if (req.method !== 'GET') {
      res.writeHead(405).end();
      return;
    }
    if (url.pathname === '/') {
      res.writeHead(200, { 'content-type': 'text/html' });
      res.end('<!doctype html><html><head><script type="module" src="/assets/index.js"></script><script src="https://cdn.example.com/x.js"></script></head><body><div id="root"></div></body></html>');
    } else if (url.pathname === '/assets/index.js') {
      res.writeHead(200, { 'content-type': 'text/javascript' });
      res.end(`const sb=createClient(location.origin,"${anon}");const admin="${fakeJwt('service_role')}";` +
        `sb.from("profiles").select();sb.from("posts").select("*");sb.from("notes").select();\n//# sourceMappingURL=index.js.map`);
    } else if (url.pathname === '/assets/index.js.map') {
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end('{"version":3,"sources":["src/App.tsx","src/lib/admin.ts"],"mappings":"AAAA"}');
    } else if (url.pathname.startsWith('/rest/v1/')) {
      if (req.headers.apikey !== anon) {
        res.writeHead(401).end('{}');
        return;
      }
      const table = url.pathname.slice('/rest/v1/'.length);
      res.writeHead(table === 'notes' ? 401 : 200, { 'content-type': 'application/json' });
      if (table === 'posts') res.end(JSON.stringify([{ id: 1, author: 'u1', body: 'private draft' }]));
      else res.end('[]');
    } else {
      res.writeHead(404).end('not found');
    }
  });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const base = `http://127.0.0.1:${server.address().port}`;
  return { base, close: () => new Promise((r) => server.close(r)) };
}
